const generateSeats = () => {
    const rows = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];
    const seats = [];
    rows.forEach(row => {
        for (let i = 1; i <= 8; i++) {
            seats.push({
                seat_location: `${row}${i}`,
                status: Math.random() > 0.2, // 80% ghế trống (true), 20% đã có người (false)
            });
        }
    });
    return seats;
};

